<script setup lang="ts">
import {readableApiError} from '../../api/client'
import {statusLabel} from '../../utils/statusLabels'
import ListPager from '../../components/ListPager.vue'
import {useListPage} from '../../composables/useListPage'
import {apiCollection} from '../../api/collections'
import { onMounted, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'
import AMapCampus from '../../components/AMapCampus.vue'
type Station={id:number;name:string;location:{name:string};address:string;opening_hours:Record<string,string>;capacity:number;status:string;latitude:number|null;longitude:number|null}
type Item={id:string;title:string;category_name:string;occurred_at:string;business_status:string}
const route=useRoute();const station=ref<Station|null>(null);const items=ref<Item[]>([]);const loading=ref(true);const error=ref('')
onMounted(async()=>{try{const [stationResponse,itemResponse]=await Promise.all([api<{data:Station}>(`/stations/${route.params.id}/`),apiCollection<{data:{items:Item[]}}>(`/items/?kind=FOUND&station=${route.params.id}`)]);station.value=stationResponse.data;items.value=itemResponse.data.items}catch(reason){error.value=readableApiError(reason,'无法读取站点详情')}finally{loading.value=false}})

const {page:pagedStationItemsPage,rows:pagedStationItems}=useListPage(items)
</script>
<template><div class="page"><p v-if="loading" class="empty">正在读取站点…</p><p v-else-if="error" class="empty error">{{error}}</p><template v-else-if="station"><header class="station-head"><div><h1 class="page-title">{{station.name}}</h1><p class="page-lead">{{station.location.name}} · {{station.address}}</p></div><span class="status-large">{{statusLabel(station.status)}}</span></header><section class="facts"><article><AppIcon name="box"/><span>保管容量</span><strong>{{station.capacity}}</strong></article><article><AppIcon name="map"/><span>工作日</span><strong>{{station.opening_hours.weekdays??'未公布'}}</strong></article><article><AppIcon name="shield"/><span>交接规则</span><strong>核对材料后领取，并按记录确认交接</strong></article></section><AMapCampus v-if="station.latitude!=null&&station.longitude!=null" compact :selected-coordinate-points="[{latitude:Number(station.latitude),longitude:Number(station.longitude),label:station.name,coordinate_system:'GCJ02'}]" /><div class="section-head"><div><h2>近期公开托管物</h2></div><span>{{items.length}} 条（当前页）</span></div><div v-if="items.length" class="item-list"><RouterLink v-for="item in pagedStationItems" :key="item.id" :to="`/items/${item.id}`" class="panel item"><div><strong>{{item.title}}</strong><small>{{item.category_name}} · {{new Date(item.occurred_at).toLocaleDateString('zh-CN')}}</small></div><span class="status-tag">{{statusLabel(item.business_status)}}</span><AppIcon name="arrow"/></RouterLink></div><p v-else class="empty">当前没有可公开展示的托管物。</p></template><ListPager :page="pagedStationItemsPage" :total="items.length" @change="pagedStationItemsPage=$event"/></div></template>
<style scoped>.station-head{display:flex;justify-content:space-between;align-items:end;gap:24px}.status-large{padding:14px 22px;color:var(--ct-success);border:1px solid rgba(54,100,75,.3);border-radius:14px;background:rgba(54,100,75,.06);font-weight:800}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:36px 0 55px}.facts article{display:grid;grid-template-columns:auto 1fr;gap:8px 13px;padding:20px;border:1px solid var(--ct-border);border-radius:14px;background:var(--ct-surface)}.facts svg{grid-row:1/3;color:var(--ct-brand);font-size:26px}.facts span{color:var(--ct-text-muted);font-size:11px}.section-head{display:flex;justify-content:space-between;align-items:end}.section-head h2{margin:7px 0 0}.section-head>span{color:var(--ct-text-muted)}.item-list{display:grid;gap:9px;margin-top:20px}.item{display:grid;grid-template-columns:1fr auto auto;gap:15px;align-items:center;padding:17px;box-shadow:none}.item small{display:block;margin-top:5px;color:var(--ct-text-muted)}.empty{display:grid;place-items:center;min-height:260px;color:var(--ct-text-muted)}.error{color:var(--ct-danger)}@media(max-width:700px){.facts{grid-template-columns:1fr}.station-head{align-items:start;flex-direction:column}.item{grid-template-columns:1fr auto}.item>svg{display:none}}</style>
